metadata.orrery:spec:
# yaml-language-server: $schema=../references/diagram.schema.json
title: Product organization
subtitle: Three levels, from the chief product officer to the teams, as an org chart
kind: tree

# Icons with the label under them are narrower than cards, so the seven teams fit one row at full
# size; each unit gets an icon of its own.
nodes:
  cpo: { icon: generic:manager, label: Chief Product Officer, note: Strategy and roadmap }
  design: { icon: tabler:palette, label: Design, note: 9 people }
  engineering: { icon: generic:code, label: Engineering, note: 24 people }
  pm: { icon: tabler:compass, label: Product management, note: 7 people }
  research: { icon: generic:search, label: User research }
  brand: { icon: tabler:brush, label: Brand and UI }
  platform: { icon: generic:server, label: Platform }
  web: { icon: generic:browser, label: Web app }
  mobile: { icon: generic:mobile, label: Mobile apps }
  growth: { icon: generic:metrics, label: Growth }
  payments: { icon: generic:payment, label: Payments }

edges:
  - cpo -> design, engineering, pm
  - design -> research, brand
  - engineering -> platform, web, mobile
  - pm -> growth, payments
